import random, time
from window import longest_unique

def independent(text):
    """Different algorithm: binary search max length + counting-window scan."""
    n = len(text)
    def feasible(L):
        if L <= 1:
            return True
        counts = {}
        dup = 0
        for i, c in enumerate(text):
            counts[c] = counts.get(c, 0) + 1
            if counts[c] == 2:
                dup += 1
            if i >= L:
                old = text[i - L]
                counts[old] -= 1
                if counts[old] == 1:
                    dup -= 1
            if i >= L - 1 and dup == 0:
                return True
        return False
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    if n == 0:
        return ''
    L = lo
    counts, dup, start = {}, 0, 0
    for i, c in enumerate(text):
        counts[c] = counts.get(c, 0) + 1
        if counts[c] == 2:
            dup += 1
        if i >= L:
            old = text[i - L]
            counts[old] -= 1
            if counts[old] == 1:
                dup -= 1
        if i >= L - 1 and dup == 0:
            return text[i - L + 1:i + 1]
    return text[:L]

random.seed(1)
N = 500_000
cases = {
    'random-4-symbol': ''.join(random.choice('abcd') for _ in range(N)),
    'random-ascii': ''.join(chr(random.randrange(128)) for _ in range(N)),
    'all-distinct': ''.join(chr(0x4E00 + i) for i in range(N)),
    'all-same': 'x' * N,
    'random-astral': ''.join(random.choice('\U0001F600\U0001F601\U0001F602') for _ in range(N)),
    'repeating-block': ('abcdefghij' * (N // 10 + 1))[:N],
}
for name, text in cases.items():
    t0 = time.perf_counter()
    got = longest_unique(text)
    dt = time.perf_counter() - t0
    exp = independent(text)
    assert got == exp, (name, len(got), len(exp))
    assert len(set(got)) == len(got)
    print(f'{name:>16}: n={len(text)} len(result)={len(got)} time={dt*1000:.1f} ms  OK')

# 1M stress
big = ''.join(random.choice('abcdefghij') for _ in range(1_000_000))
t0 = time.perf_counter(); got = longest_unique(big); dt = time.perf_counter() - t0
assert got == independent(big) and len(set(got)) == len(got)
print(f'{">1M stress":>16}: n={len(big)} len(result)={len(got)} time={dt*1000:.1f} ms  OK')
EOF","description":"Benchmark and independently verify large inputs"}

